from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
path='/root/output/result.xlsx'
wb=load_workbook(path, data_only=False)
ws=wb['Task']
# Lookup data layout: Data series codes D21:D38, year headers H4:L4, values H21:L38.
lookup_rows = list(range(12,18)) + list(range(19,25)) + list(range(26,32))
for r in lookup_rows:
    for c in range(8,13):
        col=get_column_letter(c)
        ws.cell(r,c).value = f'=INDEX(Data!$H$21:$L$38,MATCH($D{r},Data!$D$21:$D$38,0),MATCH({col}$10,Data!$H$4:$L$4,0))'

# Net SLA buffer rows 35:40 correspond to services from rows 12:17, 19:24, 26:31 respectively.
for idx, r in enumerate(range(35,41)):
    pres_row = 12 + idx
    use_row = 19 + idx
    cap_row = 26 + idx
    for c in range(8,13):
        col=get_column_letter(c)
        ws.cell(r,c).value = f'=({col}{pres_row}-{col}{use_row})/{col}{cap_row}*100'

stat_formula_by_label = {
    'minimum': 'MIN',
    'maximum': 'MAX',
    'median': 'MEDIAN',
    'simple mean': 'AVERAGE',
    '25th percentile': 'PERCENTILE25',
    '75th percentile': 'PERCENTILE75',
}
for r in range(42,48):
    label = str(ws.cell(r,5).value).strip().lower()
    for c in range(8,13):
        col=get_column_letter(c)
        if label == 'minimum':
            formula=f'=MIN({col}$35:{col}$40)'
        elif label == 'maximum':
            formula=f'=MAX({col}$35:{col}$40)'
        elif label == 'median':
            formula=f'=MEDIAN({col}$35:{col}$40)'
        elif label == 'simple mean':
            formula=f'=AVERAGE({col}$35:{col}$40)'
        elif label == '25th percentile':
            formula=f'=PERCENTILE({col}$35:{col}$40,0.25)'
        elif label == '75th percentile':
            formula=f'=PERCENTILE({col}$35:{col}$40,0.75)'
        else:
            raise ValueError(f'Unexpected stats label at E{r}: {label!r}')
        ws.cell(r,c).value = formula

for c in range(8,13):
    col=get_column_letter(c)
    ws.cell(50,c).value = f'=SUMPRODUCT({col}$35:{col}$40,{col}$26:{col}$31)/SUM({col}$26:{col}$31)'

wb.save(path)
print('Saved formulas to', path)
PY
